hl.workspace_rule({ workspace = "special:magic", on_created_empty = "kitty" })
hl.workspace_rule({ workspace = "1", on_created_empty = "firefox",                                                                         default_name = "1: Web"              })
hl.workspace_rule({ workspace = "2", on_created_empty = "firefox https://discord.com/channels/@me https://web.whatsapp.com https://mail.google.com", default_name = "2: Comms"   })
hl.workspace_rule({ workspace = "3", on_created_empty = "firefox https://calendar.google.com https://tasks.google.com https://contacts.google.com",  default_name = "3: Mission Control" })
hl.workspace_rule({ workspace = "4", on_created_empty = [[kitty /usr/bin/zsh -c "/usr/bin/zsh -c \"tmux a || tmux new-session -s home \""]], default_name = "4: Tmux"            })
hl.workspace_rule({ workspace = "5", on_created_empty = "firefox https://github.com https://gitea.lightjack.de",                           default_name = "5: GitWeb"           })
